INSERT INTO "components" ("id","name","slug","type","title","content","settings_json","status","created_at","updated_at") VALUES(7,'Review FAQ','review-faq','faq_group','Casino Frequently Asked Questions',replace('[\n  {\n    "q": "Is this casino licensed?",\n    "a": "Yes, this casino operates under a valid gaming license. Check our review summary for the specific licensing authority."\n  },\n  {\n    "q": "How fast are withdrawals?",\n    "a": "Withdrawal times vary by payment method. E-wallets typically process within 24 hours, while bank transfers may take 3–5 business days."\n  },\n  {\n    "q": "Does this casino accept crypto?",\n    "a": "Check our payment methods section above for the full list of accepted cryptocurrencies and traditional payment options."\n  },\n  {\n    "q": "Is there a welcome bonus?",\n    "a": "Most casinos offer a welcome bonus for new players. Visit the bonuses section of this review to see the latest welcome offer, wagering requirements, and eligibility."\n  },\n  {\n    "q": "What games are available?",\n    "a": "The casino typically offers a wide selection of slots, table games, live dealer titles, jackpots, and other popular casino games. See the games section above for details."\n  },\n  {\n    "q": "Can I play on mobile devices?",\n    "a": "Yes, most modern online casinos support mobile play through responsive websites or dedicated apps. Check our review to confirm compatibility with your device."\n  },\n  {\n    "q": "Which payment methods are supported?",\n    "a": "Available payment options may include credit and debit cards, bank transfers, e-wallets, prepaid solutions, and cryptocurrencies. Refer to the payments section for the complete list."\n  },\n  {\n    "q": "Is customer support available 24/7?",\n    "a": "Many online casinos provide round-the-clock customer support through live chat, email, or other contact methods. See our review for the support channels offered."\n  },\n  {\n    "q": "Can players from my country