INSERT INTO "ai_conversations" ("id","session_id","user_id","messages","created_at","updated_at") VALUES('be594016-4f60-491d-a56e-031847d4887f','lummet-1789329986596-08wydkue',NULL,'[{"role":"user","content":"What is level.casino?","ts":1789329999157},{"role":"assistant","content":"I couldn''t find that information in the level.casino database. You can browse our independent casino reviews, guides, news, and responsible gambling resources at https://level.casino/en/ — or contact us at https://level.casino/en/contact and we''ll be happy to help.","ts":1789329999157}]','2026-09-13 20:06:37','2026-09-13 20:06:39');
